}

Method.Source:
/// <summary>
/// If run for Unified pricing service - only Sales price journal names are available
/// </summary>
/// <param name="_sender">Data source</param>
/// <param name="_e">Param</param>
[FormDataSourceEventHandler(formDataSourceStr(PriceDiscAdmName, PriceDiscAdmName), FormDataSourceEventType::Initialized)]
public static void PriceDiscAdmName_OnInitialized(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    if (_sender.formRun().args().menuItemName() == menuItemDisplayStr(UPSPriceDiscAdmName_Sales))
    {
        _sender.object(fieldNum(PriceDiscAdmName, PriceDiscPriceAttributeEnable)).visible(true);
        _sender.object(fieldNum(PriceDiscAdmName, DefaultRelation)).allowEdit(false);
        _sender.queryBuildDataSource().addRange(fieldNum(PriceDiscAdmName, DefaultRelation)).value(queryValue(PriceType::PriceSales));
    }
    else
    {
        _sender.object(fieldNum(PriceDiscAdmName, PriceDiscPriceAttributeEnable)).visible(false);
    }
}
